@spec tv_param_bind_spec  src=tests/specs/tv_param_bind_spec.lua  loc=119  cases=4
@exercises trackerView (h.vm), editCursor (h.ec), dataStore (h.ds)
@surface   vm:setGridSize, ec:setPos, vm:setPaletteParam, vm:automateParam, vm:paramBinding, ds:get, vm:rebuild, vm:unautomateParam, vm:hideExtraCol
@harness   mk{seed.notes, seed.ccs}, r:seedMidi, r._state.projectTracks, r._state.projectItems, r._state.takeIsMidi

# Intent
  Binding mutations through the real tv path. automateParam binds the
  palette param at the cursor channel, and tm derives its cc column from
  the binding -- nothing is written per take; unautomateParam empties the
  lane, then column + binding go via hideExtraCol; hideExtraCol alone also
  drops the binding of an empty bound column. Real trackerView + real
  paramAutomation via harness.mk.

# Helpers
  @fn ccColIndex(h, cc)  @ 16-20

# Cases
  @case 'automateParam binds the palette param and tm derives its cc column'  [harness]  @ 25-51
  @case 'allocation skips authored cc columns and event-bearing ccs'  [harness]  @ 55-75
  @case 'unautomateParam deletes lane events then removes column and binding'  [harness]  @ 79-98
  @case 'hideExtraCol on an empty bound cc column drops the binding'  [harness]  @ 102-116

# Uses (outbound edges)
  @use call vm:setGridSize  @ 31,68,89,108
  @use call ec:setPos  @ 32,69,93,111
  @use call vm:setPaletteParam  @ 33,46,70
  @use call vm:automateParam  @ 34,47,71
  @use call vm:paramBinding  @ 36,48,73,96,114
  @use call ds:get  @ 41
